<script setup lang="ts">
import { canViewProjectSection } from '~~/shared/utils/project-permissions'
import {useQuery} from '@tanstack/vue-query'
import BrandLogo from '~/components/Brand/BrandLogo.vue'
const emit=defineEmits<{navigate:[]}>()
const route=useRoute(),projects=useProjectsData(),access=useProjectAccess(),auth=useAuthStore()
const {search,folder}=useKabanDirectoryNavigation(),expanded=ref<string[]>([])
const folders=useQuery({queryKey:computed(()=>['account',auth.user?.id,'project-folders']),queryFn:()=>sharedRequest<{id:string;name:string}[]>('/api/projects/folders'),enabled:computed(()=>access.data.value?.allowed===true),retry:false})
const visible=computed(()=>(projects.data.value??[]).filter(p=>canViewProjectSection(p, 'tasks')&&!p.profile?.archived&&p.name.toLocaleLowerCase('ru').includes(search.value.trim().toLocaleLowerCase('ru'))))
function chooseFolder(id:string){folder.value=id;if(expanded.value.includes(id))expanded.value=expanded.value.filter(value=>value!==id);else expanded.value.push(id);navigateTo('/kaban');emit('navigate')}
</script>
<template><div class="kaban-navigation"><BrandLogo/><UInput v-model="search" icon="i-lucide-search" placeholder="Проект…" aria-label="Поиск проектов" class="w-full"/><nav><NuxtLink v-for="item in [{view:'mine',label:'Мои задачи',icon:'i-lucide-user-round-check'},{view:'all',label:'Все задачи',icon:'i-lucide-list-todo'},{view:'calendar',label:'Календарь задач',icon:'i-lucide-calendar-days'},{view:'gantt',label:'Диаграмма Ганта',icon:'i-lucide-chart-gantt'},{view:'projects',label:'Все проекты',icon:'i-lucide-folder-kanban'}]" :key="item.view" :to="item.view==='projects'?'/kaban':`/kaban?view=${item.view}`" :aria-current="(route.query.view||'projects')===item.view&&(item.view==='calendar'||item.view==='gantt'||folder==='all')?'page':undefined" @click="folder='all';emit('navigate')"><UIcon :name="item.icon"/>{{item.label}}</NuxtLink></nav><div class="navigation-label"><span>Проекты</span><UButton to="/projects?create=1" icon="i-lucide-plus" color="neutral" variant="ghost" aria-label="Добавить проект" @click="emit('navigate')"/></div><nav v-if="access.data.value?.allowed"><NuxtLink v-for="p in visible.filter(p=>!p.folderId)" :key="p.id" :to="`/projects/${p.id}/tasks`" @click="emit('navigate')"><img v-if="p.profile?.avatar" :src="p.profile.avatar" alt=""/><UIcon v-else name="i-lucide-columns-3"/><span>{{p.name}}</span></NuxtLink><template v-for="f in folders.data.value" :key="f.id"><button :aria-current="folder===f.id?'page':undefined" :aria-expanded="expanded.includes(f.id)||!!search.trim()" @click="chooseFolder(f.id)"><UIcon name="i-lucide-folder"/><span>{{f.name}}</span><UIcon name="i-lucide-chevron-down"/></button><div v-if="expanded.includes(f.id)||search.trim()" class="folder-projects"><NuxtLink v-for="p in visible.filter(p=>p.folderId===f.id)" :key="p.id" :to="`/projects/${p.id}/tasks`" @click="emit('navigate')"><UIcon name="i-lucide-columns-3"/><span>{{p.name}}</span></NuxtLink></div></template><p v-if="!visible.length" class="empty">Проекты не найдены</p></nav><div class="navigation-bottom"><NuxtLink to="/" @click="emit('navigate')"><UIcon name="i-lucide-arrow-left"/>К приложениям</NuxtLink></div></div></template>
<style scoped>
.kaban-navigation{padding:28px 16px;display:flex;flex-direction:column;gap:24px;min-height:100%}.kaban-navigation nav{display:grid;gap:5px}.kaban-navigation a:not(.brand),.kaban-navigation nav>button{display:flex;align-items:center;gap:10px;padding:12px;border-radius:10px;color:#8292a8;font-size:13px;min-width:0;text-align:left;justify-content:flex-start}.kaban-navigation nav a:hover,.kaban-navigation nav>button:hover,.kaban-navigation a[aria-current=page],.kaban-navigation nav>button[aria-current=page]{background:#f1f3f8;color:var(--ui-primary)}.kaban-navigation .iconify,.kaban-navigation nav img{width:19px;height:19px;flex:0 0 19px;border-radius:5px;object-fit:cover}.kaban-navigation nav span:not(.iconify){overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1}.navigation-label{display:flex;align-items:center;justify-content:space-between;font-size:12px;color:#94a3b8;padding:0 10px;margin-bottom:-14px}.folder-projects{padding-left:16px;border-left:1px solid #e2e8f0;margin-left:12px}.navigation-bottom{margin-top:auto;border-top:1px solid #e8edf3;padding-top:18px}.empty{color:#94a3b8;font-size:12px;padding:12px}
</style>
